export default {"file":"driver-dashboard.html","title":"Driver Dashboard - Schoolix","htmlClass":"","bodyClass":"","body":"\n<main class=\"driver-shell\">\n  <section class=\"panel top\">\n    <div>\n      <h1>Driver Dashboard</h1>\n      <p class=\"muted\">Tracking is controlled by the school administrator.</p>\n    </div>\n    <button class=\"secondary\" id=\"logoutBtn\">Logout</button>\n  </section>\n\n  <section class=\"panel permission\" id=\"permissionPanel\" hidden>\n    <h2 style=\"margin:0 0 8px;font-size:18px;\">Location Permission Required</h2>\n    <p class=\"muted\">Schoolix needs your location while you are driving so your assigned school vehicle can be tracked when the administrator activates a trip.</p>\n    <button id=\"grantPermissionBtn\">Grant Location Permission</button>\n  </section>\n\n  <section class=\"panel\">\n    <div class=\"grid\">\n      <div class=\"metric\"><strong>Driver</strong><span id=\"driverName\">Loading...</span></div>\n      <div class=\"metric\"><strong>Vehicle</strong><span id=\"vehicleNumber\">-</span></div>\n      <div class=\"metric\"><strong>Trip Status</strong><span id=\"tripStatus\">-</span></div>\n      <div class=\"metric\"><strong>Location Tracking</strong><span id=\"trackingStatus\" class=\"badge off\">OFF</span></div>\n      <div class=\"metric\"><strong>GPS</strong><span id=\"gpsStatus\">Checking...</span></div>\n      <div class=\"metric\"><strong>Last Location Update</strong><span id=\"lastUpdate\">-</span></div>\n    </div>\n  </section>\n\n  <section class=\"panel\">\n    <h2 style=\"margin:0 0 12px;font-size:18px;\">Assigned Vehicle</h2>\n    <div class=\"map\" id=\"driverMap\"></div>\n    <p class=\"muted\" id=\"driverNote\">No start or stop controls are available on driver accounts.</p>\n  </section>\n</main>\n\n<script type=\"module\">\nimport { initializeApp, getAuth, getFirestore, onAuthStateChanged, signOut, doc, getDoc, collection, getDocs, query, where } from \"./firebase-compat.js\";\nimport { activeTrips, accessToken, myDriverProfile, subscribeTransport, upsertLiveLocation } from \"./schoolix-transport.js\";\nimport { calibratedSpeedKmh, createVehicleMap } from \"./schoolix-maplibre.js\";\n\nconst app = initializeApp({ projectId: \"schoolix-48107\" });\nconst auth = getAuth(app);\nconst db = getFirestore(app);\nconst $ = (id) => document.getElementById(id);\nconst state = { user: null, profile: null, activeTrip: null, watchId: null, lastLocationAt: null, map: null, lastUploadAt: 0, nativeTripId: null, lastPosition: null };\n\nfunction setText(id, value) { $(id).textContent = value || \"-\"; }\nfunction setTracking(on) {\n  $(\"trackingStatus\").textContent = on ? \"ON\" : \"OFF\";\n  $(\"trackingStatus\").className = `badge ${on ? \"on\" : \"off\"}`;\n  setText(\"tripStatus\", on ? \"ACTIVE\" : \"NOT ACTIVE\");\n}\nfunction relativeTime(value) {\n  if (!value) return \"-\";\n  const seconds = Math.max(0, Math.round((Date.now() - new Date(value).getTime()) / 1000));\n  if (seconds < 60) return `${seconds} seconds ago`;\n  return `${Math.round(seconds / 60)} minutes ago`;\n}\nfunction hasNativeBridge() { return Boolean(window.SchoolixNativeLocation?.startTracking); }\nasync function locationPermissionReady() {\n  if (hasNativeBridge() && window.SchoolixNativeLocation.hasLocationPermission) {\n    return window.SchoolixNativeLocation.hasLocationPermission() === \"true\";\n  }\n  if (!navigator.permissions?.query) return Boolean(navigator.geolocation);\n  try {\n    const status = await navigator.permissions.query({ name: \"geolocation\" });\n    return status.state === \"granted\";\n  } catch (_) {\n    return Boolean(navigator.geolocation);\n  }\n}\nasync function updatePermissionUi() {\n  const ready = await locationPermissionReady();\n  $(\"permissionPanel\").hidden = ready;\n  setText(\"gpsStatus\", ready ? \"Connected\" : \"Permission needed\");\n  return ready;\n}\nfunction stopBrowserWatch() {\n  if (state.watchId != null) navigator.geolocation?.clearWatch(state.watchId);\n  state.watchId = null;\n}\nfunction stopTracking() {\n  try { window.SchoolixNativeLocation?.stopTracking?.(); } catch (_) {}\n  state.nativeTripId = null;\n  state.activeTrip = null;\n  state.lastUploadAt = 0;\n  setTracking(false);\n  $(\"logoutBtn\").disabled = false;\n  $(\"logoutBtn\").title = \"\";\n  setText(\"driverNote\", \"Tracking is controlled by the school administrator. Logout is available when tracking is OFF.\");\n}\nasync function sendBrowserLocation(position) {\n  if (!state.profile?.vehicle) return;\n  state.lastPosition = position;\n  const coords = position.coords;\n  const speed = calibratedSpeedKmh(coords.speed, \"mps\");\n  const updatedAt = new Date().toISOString();\n  state.map?.setVehicle(state.profile.vehicle.id, {\n    latitude: coords.latitude,\n    longitude: coords.longitude,\n    speed,\n    heading: coords.heading,\n    accuracy: coords.accuracy,\n    updated_at: updatedAt\n  }, state.profile.vehicle.vehicle_number || \"Vehicle\", {\n    driver: `${state.profile.name || \"You\"} - You are here`,\n    status: \"live\"\n  });\n  setText(\"gpsStatus\", \"GPS connected\");\n  if (!state.activeTrip || Date.now() - state.lastUploadAt < 3000) return;\n  state.lastUploadAt = Date.now();\n  try {\n    await upsertLiveLocation({\n      school_id: state.profile.school_id,\n      vehicle_id: state.profile.vehicle.id,\n      trip_id: state.activeTrip.id,\n      latitude: coords.latitude,\n      longitude: coords.longitude,\n      speed,\n      heading: coords.heading,\n      accuracy: coords.accuracy,\n      updated_at: updatedAt\n    });\n    state.lastLocationAt = updatedAt;\n    setText(\"gpsStatus\", \"Live location shared\");\n    setText(\"lastUpdate\", \"just now\");\n  } catch (error) {\n    console.warn(\"Live location upload failed\", error);\n    setText(\"gpsStatus\", \"Upload retrying\");\n  }\n}\n\nfunction startBrowserWatch() {\n  stopBrowserWatch();\n  if (!navigator.geolocation) {\n    setText(\"gpsStatus\", \"GPS unavailable\");\n    return;\n  }\n  navigator.geolocation.getCurrentPosition(sendBrowserLocation, () => {\n    setText(\"gpsStatus\", \"GPS unavailable\");\n  }, { enableHighAccuracy: true, maximumAge: 0, timeout: 15000 });\n  state.watchId = navigator.geolocation.watchPosition(sendBrowserLocation, () => {\n    setText(\"gpsStatus\", \"GPS unavailable\");\n  }, { enableHighAccuracy: true, maximumAge: 5000, timeout: 15000 });\n}\n\nasync function startTracking(trip) {\n  state.activeTrip = trip;\n  state.lastUploadAt = 0;\n  $(\"logoutBtn\").disabled = true;\n  $(\"logoutBtn\").title = \"Admin must stop location tracking before logout\";\n  setTracking(true);\n  const ready = await updatePermissionUi();\n  if (state.lastPosition) sendBrowserLocation(state.lastPosition);\n  if (state.watchId == null) startBrowserWatch();\n  if (!ready) return;\n  if (hasNativeBridge() && state.nativeTripId !== trip.id) {\n    state.nativeTripId = trip.id;\n    window.SchoolixNativeLocation.startTracking(JSON.stringify({\n      supabaseUrl: \"https://ezkmeedcqetztkeppxil.supabase.co\",\n      anonKey: \"eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImV6a21lZWRjcWV0enRrZXBweGlsIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzgxMjk5NjAsImV4cCI6MjA5MzcwNTk2MH0.1davJ_NYkFhHToUtcFBR0kA6dk0-cOkaIbK2SCObkQg\",\n      accessToken: accessToken(),\n      schoolId: state.profile.school_id,\n      vehicleId: state.profile.vehicle.id,\n      tripId: trip.id\n    }));\n  }\n}\nasync function refreshTrip() {\n  const vehicleId = state.profile?.vehicle?.id;\n  if (!vehicleId) return stopTracking();\n  const trips = await activeTrips([vehicleId]);\n  if (trips.length) await startTracking(trips[0]);\n  else stopTracking();\n}\nasync function findDriverUserProfile(user) {\n  const direct = await getDoc(doc(db, \"users\", user.uid)).catch(() => null);\n  if (direct?.exists?.()) return { id: direct.id, ...direct.data() };\n  const lookups = [\n    [\"authUid\", user.supabaseUid || user.uid],\n    [\"uid\", user.supabaseUid || user.uid],\n    [\"email\", user.email || \"\"],\n    [\"authEmail\", user.email || \"\"]\n  ].filter(([, value]) => String(value || \"\").trim());\n  for (const [field, value] of lookups) {\n    const snap = await getDocs(query(collection(db, \"users\"), where(field, \"==\", value))).catch(() => null);\n    if (snap && !snap.empty) return { id: snap.docs[0].id, ...snap.docs[0].data() };\n  }\n  return null;\n}\n\nasync function fallbackDriverProfile(user) {\n  const userProfile = await findDriverUserProfile(user);\n  const vehicleId = userProfile?.assignedVehicleId || userProfile?.vehicleId || \"\";\n  if (!userProfile || !vehicleId) return null;\n  const vehicleSnap = await getDoc(doc(db, \"schools\", userProfile.schoolId || userProfile.adminId, \"vehicles\", vehicleId)).catch(() => null);\n  const vehicle = vehicleSnap?.exists?.() ? { id: vehicleSnap.id, ...vehicleSnap.data() } : null;\n  return {\n    id: userProfile.driverId || userProfile.transportDriverId || userProfile.id,\n    school_id: userProfile.schoolId || userProfile.adminId,\n    name: userProfile.name || userProfile.driverName || user.email,\n    phone: userProfile.phone || \"\",\n    email: userProfile.email || user.email,\n    vehicle: vehicle ? {\n      id: vehicle.id,\n      vehicle_number: vehicle.vehicleNumber || vehicle.vehicle_number,\n      vehicle_type: vehicle.vehicleType || vehicle.vehicle_type,\n      route_id: vehicle.routeId || null,\n      data: vehicle\n    } : null\n  };\n}\n\nasync function loadDriver() {\n  let profile = await myDriverProfile().catch((error) => {\n    console.warn(\"Supabase driver profile unavailable, using Firestore fallback\", error);\n    return null;\n  });\n  if (!profile) profile = await fallbackDriverProfile(state.user);\n  state.profile = profile;\n  if (!profile) {\n    setText(\"driverName\", \"Driver profile not found\");\n    setText(\"driverNote\", \"Admin se vehicle edit karke driver email/password save karwao, phir login retry karo.\");\n    return;\n  }\n  setText(\"driverName\", profile.name);\n  setText(\"vehicleNumber\", profile.vehicle?.vehicle_number || \"Not assigned\");\n  state.map = await createVehicleMap($(\"driverMap\"), { zoom: 15 });\n  await updatePermissionUi();\n  startBrowserWatch();\n  await refreshTrip();\n  if (profile.vehicle?.id) {\n    subscribeTransport(\"schoolix_transport_trips\", `vehicle_id=eq.${profile.vehicle.id}`, refreshTrip, refreshTrip);\n  }\n}\nwindow.SchoolixNativeLocationStatus = {\n  receiveStatus(payload = {}) {\n    setText(\"gpsStatus\", payload.status || \"Connected\");\n    if (payload.updatedAt) setText(\"lastUpdate\", relativeTime(payload.updatedAt));\n  }\n};\n$(\"grantPermissionBtn\").addEventListener(\"click\", async () => {\n  if (window.SchoolixNativeLocation?.requestLocationPermission) window.SchoolixNativeLocation.requestLocationPermission();\n  else navigator.geolocation?.getCurrentPosition(() => updatePermissionUi(), () => updatePermissionUi(), { enableHighAccuracy: true });\n  setTimeout(updatePermissionUi, 1200);\n});\n$(\"logoutBtn\").addEventListener(\"click\", async () => {\n  if (state.activeTrip || state.nativeTripId || $(\"trackingStatus\").classList.contains(\"on\")) {\n    setText(\"driverNote\", \"Logout is locked while location tracking is ON. Ask the administrator to stop the trip first.\");\n    return;\n  }\n  stopBrowserWatch();\n  await signOut(auth);\n  location.href = \"#/index.html\";\n});\nsetInterval(() => setText(\"lastUpdate\", relativeTime(state.lastLocationAt)), 3000);\nonAuthStateChanged(auth, async (user) => {\n  if (!user) { location.href = \"#/index.html\"; return; }\n  state.user = user;\n  const userProfile = await findDriverUserProfile(user);\n  if (!userProfile || String(userProfile.role || \"\").toLowerCase() !== \"driver\") {\n    alert(\"Access denied. Driver account required.\");\n    location.href = \"#/index.html\";\n    return;\n  }\n  await loadDriver();\n});\n</script>\n<script src=\"schoolix-polish.js\" defer></script>\n","styles":[{"tag":"link","attributes":{"rel":"stylesheet","href":"schoolix-app.css"},"text":"\n<style>\nbody { margin:0; font-family:\"Segoe UI\",sans-serif; background:#f4f7fb; color:#0f172a; }\n.driver-shell { max-width:860px; margin:0 auto; padding:20px; }\n.panel { background:#fff; border:1px solid #e2e8f0; border-radius:8px; padding:18px; margin-bottom:14px; box-shadow:0 12px 28px rgba(15,23,42,.06); }\n.top { display:flex; align-items:center; justify-content:space-between; gap:12px; flex-wrap:wrap; }\nh1 { margin:0; font-size:24px; }\n.muted { color:#64748b; margin-top:5px; }\n.grid { display:grid; grid-template-columns:repeat(auto-fit,minmax(190px,1fr)); gap:12px; }\n.metric { border:1px solid #e2e8f0; border-radius:8px; padding:14px; background:#f8fafc; }\n.metric strong { display:block; font-size:12px; color:#64748b; text-transform:uppercase; letter-spacing:.06em; margin-bottom:6px; }\n.metric span { font-weight:700; font-size:17px; }\n.badge { display:inline-flex; align-items:center; gap:7px; border-radius:999px; padding:7px 11px; font-weight:800; font-size:12px; }\n.badge.on { background:#dcfce7; color:#166534; }\n.badge.off { background:#fee2e2; color:#991b1b; }\n.permission { border:1px solid #bfdbfe; background:#eff6ff; }\nbutton { border:0; border-radius:8px; padding:10px 14px; font-weight:700; cursor:pointer; background:#2563eb; color:#fff; }\nbutton.secondary { background:#e2e8f0; color:#0f172a; }\n.map { height:300px; border:1px solid #cbd5e1; border-radius:8px; overflow:hidden; background:#e0f2fe; position:relative; }\n.sx-map-fallback { height:100%; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:8px; text-align:center; color:#334155; padding:18px; }\n.sx-map-fallback span { color:#64748b; font-size:13px; }\n.sx-map-recenter { position:absolute; left:14px; bottom:14px; z-index:3; min-height:34px; padding:8px 12px; background:#fff; color:#2563eb; border:1px solid #cbd5e1; }\n.sx-vehicle-marker { width:auto; height:42px; min-width:42px; border:0; background:transparent; box-shadow:none; display:inline-flex; align-items:center; gap:8px; color:#101828; }\n.sx-vehicle-marker-dot { width:42px; height:42px; display:block; border-radius:999px; background:transparent; border:0; box-shadow:0 8px 18px rgba(16,24,40,.28); animation:sxVehicleFloat 1.7s ease-in-out infinite; }\n.sx-vehicle-avatar { width:42px; height:42px; display:block; }\n.sx-vehicle-avatar-pulse { fill:rgba(22,130,85,.18); animation:sxVehiclePulse 1.6s ease-out infinite; transform-origin:center; }\n.sx-vehicle-avatar-body { fill:#168255; stroke:#fff; stroke-width:2.2; }\n.sx-vehicle-avatar-window { fill:#e0f2fe; }\n.sx-vehicle-avatar-light { stroke:#fff; stroke-width:2.2; stroke-linecap:round; }\n.sx-vehicle-avatar-wheel { fill:#172033; stroke:#fff; stroke-width:1.4; }\n.sx-vehicle-marker[data-status=\"stale\"] .sx-vehicle-avatar-body { fill:#d97706; }\n.sx-vehicle-marker-label { display:grid; gap:1px; max-width:190px; padding:6px 9px; border:1px solid rgba(16,24,40,.12); border-radius:8px; background:rgba(255,255,255,.96); box-shadow:0 8px 18px rgba(16,24,40,.16); line-height:1.1; }\n.sx-vehicle-marker-label strong,.sx-vehicle-marker-label small { overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }\n.sx-vehicle-marker-label strong { color:#101828; font-size:12px; font-weight:900; }\n.sx-vehicle-marker-label small { color:#667085; font-size:11px; font-weight:800; }\n@keyframes sxVehicleFloat { 0%,100%{transform:translateY(0) rotate(-1deg)} 50%{transform:translateY(-3px) rotate(1deg)} }\n@keyframes sxVehiclePulse { 0%{transform:scale(.72);opacity:.85} 100%{transform:scale(1.25);opacity:0} }\n.sx-map-popup { min-width:170px; font:13px/1.45 \"Segoe UI\", sans-serif; color:#172033; }\n.sx-map-popup strong { display:block; font-size:14px; margin-bottom:4px; }\n.sx-map-popup span { display:inline-flex; margin-bottom:6px; padding:2px 7px; border-radius:999px; background:#e7f8ef; color:#16794f; font-weight:800; font-size:11px; }\nbody { background:#070b14; color:#e8eef8; }\n.driver-shell { max-width:1100px; padding:24px; }\n.panel { background:#101827; border-color:#26364d; border-radius:14px; box-shadow:0 18px 48px rgba(0,0,0,.22); }\n.top { padding:20px 22px; }\nh1 { color:#f8fafc; letter-spacing:0; }\n.muted { color:#9aacbf; }\n.metric { background:#0c1422; border-color:#26364d; }\n.metric strong { color:#8fa3ba; letter-spacing:.04em; }\n.metric span { color:#f8fafc; }\n.badge.on { background:rgba(45,212,191,.16); color:#99f6e4; border:1px solid rgba(45,212,191,.28); }\n.badge.off { background:rgba(248,113,113,.13); color:#fecaca; border:1px solid rgba(248,113,113,.24); }\n.permission { background:#10233d; border-color:#2f6fb2; }\nbutton { background:#2563eb; color:#fff; box-shadow:0 10px 22px rgba(37,99,235,.22); }\nbutton.secondary { background:#182337; color:#dbeafe; border:1px solid #30425f; box-shadow:none; }\nbutton:disabled { opacity:.48; cursor:not-allowed; box-shadow:none; }\n.map { min-height:360px; height:min(56vh,560px); background:#0b1320; border-color:#2c3b54; }\n.sx-map-recenter { background:#101c2e; color:#8fd3ff; border-color:#38506e; }\n.sx-vehicle-marker-label { background:rgba(10,18,31,.94); border-color:#38506e; box-shadow:0 8px 20px rgba(0,0,0,.3); }\n.sx-vehicle-marker-label strong { color:#f8fafc; }\n.sx-vehicle-marker-label small { color:#a8bad1; }\n.sx-map-popup { color:#172033; }\n@media (max-width:640px) { .driver-shell { padding:14px; } .panel { padding:15px; } .top { padding:17px; } h1 { font-size:21px; } .map { min-height:310px; height:52vh; } }\n"},{"tag":"link","attributes":{"rel":"stylesheet","href":"schoolix-polish.css"},"text":""}],"scripts":[{"attributes":{"type":"module"},"text":"\nimport { initializeApp, getAuth, getFirestore, onAuthStateChanged, signOut, doc, getDoc, collection, getDocs, query, where } from \"./firebase-compat.js\";\nimport { activeTrips, accessToken, myDriverProfile, subscribeTransport, upsertLiveLocation } from \"./schoolix-transport.js\";\nimport { calibratedSpeedKmh, createVehicleMap } from \"./schoolix-maplibre.js\";\n\nconst app = initializeApp({ projectId: \"schoolix-48107\" });\nconst auth = getAuth(app);\nconst db = getFirestore(app);\nconst $ = (id) => document.getElementById(id);\nconst state = { user: null, profile: null, activeTrip: null, watchId: null, lastLocationAt: null, map: null, lastUploadAt: 0, nativeTripId: null, lastPosition: null };\n\nfunction setText(id, value) { $(id).textContent = value || \"-\"; }\nfunction setTracking(on) {\n  $(\"trackingStatus\").textContent = on ? \"ON\" : \"OFF\";\n  $(\"trackingStatus\").className = `badge ${on ? \"on\" : \"off\"}`;\n  setText(\"tripStatus\", on ? \"ACTIVE\" : \"NOT ACTIVE\");\n}\nfunction relativeTime(value) {\n  if (!value) return \"-\";\n  const seconds = Math.max(0, Math.round((Date.now() - new Date(value).getTime()) / 1000));\n  if (seconds < 60) return `${seconds} seconds ago`;\n  return `${Math.round(seconds / 60)} minutes ago`;\n}\nfunction hasNativeBridge() { return Boolean(window.SchoolixNativeLocation?.startTracking); }\nasync function locationPermissionReady() {\n  if (hasNativeBridge() && window.SchoolixNativeLocation.hasLocationPermission) {\n    return window.SchoolixNativeLocation.hasLocationPermission() === \"true\";\n  }\n  if (!navigator.permissions?.query) return Boolean(navigator.geolocation);\n  try {\n    const status = await navigator.permissions.query({ name: \"geolocation\" });\n    return status.state === \"granted\";\n  } catch (_) {\n    return Boolean(navigator.geolocation);\n  }\n}\nasync function updatePermissionUi() {\n  const ready = await locationPermissionReady();\n  $(\"permissionPanel\").hidden = ready;\n  setText(\"gpsStatus\", ready ? \"Connected\" : \"Permission needed\");\n  return ready;\n}\nfunction stopBrowserWatch() {\n  if (state.watchId != null) navigator.geolocation?.clearWatch(state.watchId);\n  state.watchId = null;\n}\nfunction stopTracking() {\n  try { window.SchoolixNativeLocation?.stopTracking?.(); } catch (_) {}\n  state.nativeTripId = null;\n  state.activeTrip = null;\n  state.lastUploadAt = 0;\n  setTracking(false);\n  $(\"logoutBtn\").disabled = false;\n  $(\"logoutBtn\").title = \"\";\n  setText(\"driverNote\", \"Tracking is controlled by the school administrator. Logout is available when tracking is OFF.\");\n}\nasync function sendBrowserLocation(position) {\n  if (!state.profile?.vehicle) return;\n  state.lastPosition = position;\n  const coords = position.coords;\n  const speed = calibratedSpeedKmh(coords.speed, \"mps\");\n  const updatedAt = new Date().toISOString();\n  state.map?.setVehicle(state.profile.vehicle.id, {\n    latitude: coords.latitude,\n    longitude: coords.longitude,\n    speed,\n    heading: coords.heading,\n    accuracy: coords.accuracy,\n    updated_at: updatedAt\n  }, state.profile.vehicle.vehicle_number || \"Vehicle\", {\n    driver: `${state.profile.name || \"You\"} - You are here`,\n    status: \"live\"\n  });\n  setText(\"gpsStatus\", \"GPS connected\");\n  if (!state.activeTrip || Date.now() - state.lastUploadAt < 3000) return;\n  state.lastUploadAt = Date.now();\n  try {\n    await upsertLiveLocation({\n      school_id: state.profile.school_id,\n      vehicle_id: state.profile.vehicle.id,\n      trip_id: state.activeTrip.id,\n      latitude: coords.latitude,\n      longitude: coords.longitude,\n      speed,\n      heading: coords.heading,\n      accuracy: coords.accuracy,\n      updated_at: updatedAt\n    });\n    state.lastLocationAt = updatedAt;\n    setText(\"gpsStatus\", \"Live location shared\");\n    setText(\"lastUpdate\", \"just now\");\n  } catch (error) {\n    console.warn(\"Live location upload failed\", error);\n    setText(\"gpsStatus\", \"Upload retrying\");\n  }\n}\n\nfunction startBrowserWatch() {\n  stopBrowserWatch();\n  if (!navigator.geolocation) {\n    setText(\"gpsStatus\", \"GPS unavailable\");\n    return;\n  }\n  navigator.geolocation.getCurrentPosition(sendBrowserLocation, () => {\n    setText(\"gpsStatus\", \"GPS unavailable\");\n  }, { enableHighAccuracy: true, maximumAge: 0, timeout: 15000 });\n  state.watchId = navigator.geolocation.watchPosition(sendBrowserLocation, () => {\n    setText(\"gpsStatus\", \"GPS unavailable\");\n  }, { enableHighAccuracy: true, maximumAge: 5000, timeout: 15000 });\n}\n\nasync function startTracking(trip) {\n  state.activeTrip = trip;\n  state.lastUploadAt = 0;\n  $(\"logoutBtn\").disabled = true;\n  $(\"logoutBtn\").title = \"Admin must stop location tracking before logout\";\n  setTracking(true);\n  const ready = await updatePermissionUi();\n  if (state.lastPosition) sendBrowserLocation(state.lastPosition);\n  if (state.watchId == null) startBrowserWatch();\n  if (!ready) return;\n  if (hasNativeBridge() && state.nativeTripId !== trip.id) {\n    state.nativeTripId = trip.id;\n    window.SchoolixNativeLocation.startTracking(JSON.stringify({\n      supabaseUrl: \"https://ezkmeedcqetztkeppxil.supabase.co\",\n      anonKey: \"eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImV6a21lZWRjcWV0enRrZXBweGlsIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzgxMjk5NjAsImV4cCI6MjA5MzcwNTk2MH0.1davJ_NYkFhHToUtcFBR0kA6dk0-cOkaIbK2SCObkQg\",\n      accessToken: accessToken(),\n      schoolId: state.profile.school_id,\n      vehicleId: state.profile.vehicle.id,\n      tripId: trip.id\n    }));\n  }\n}\nasync function refreshTrip() {\n  const vehicleId = state.profile?.vehicle?.id;\n  if (!vehicleId) return stopTracking();\n  const trips = await activeTrips([vehicleId]);\n  if (trips.length) await startTracking(trips[0]);\n  else stopTracking();\n}\nasync function findDriverUserProfile(user) {\n  const direct = await getDoc(doc(db, \"users\", user.uid)).catch(() => null);\n  if (direct?.exists?.()) return { id: direct.id, ...direct.data() };\n  const lookups = [\n    [\"authUid\", user.supabaseUid || user.uid],\n    [\"uid\", user.supabaseUid || user.uid],\n    [\"email\", user.email || \"\"],\n    [\"authEmail\", user.email || \"\"]\n  ].filter(([, value]) => String(value || \"\").trim());\n  for (const [field, value] of lookups) {\n    const snap = await getDocs(query(collection(db, \"users\"), where(field, \"==\", value))).catch(() => null);\n    if (snap && !snap.empty) return { id: snap.docs[0].id, ...snap.docs[0].data() };\n  }\n  return null;\n}\n\nasync function fallbackDriverProfile(user) {\n  const userProfile = await findDriverUserProfile(user);\n  const vehicleId = userProfile?.assignedVehicleId || userProfile?.vehicleId || \"\";\n  if (!userProfile || !vehicleId) return null;\n  const vehicleSnap = await getDoc(doc(db, \"schools\", userProfile.schoolId || userProfile.adminId, \"vehicles\", vehicleId)).catch(() => null);\n  const vehicle = vehicleSnap?.exists?.() ? { id: vehicleSnap.id, ...vehicleSnap.data() } : null;\n  return {\n    id: userProfile.driverId || userProfile.transportDriverId || userProfile.id,\n    school_id: userProfile.schoolId || userProfile.adminId,\n    name: userProfile.name || userProfile.driverName || user.email,\n    phone: userProfile.phone || \"\",\n    email: userProfile.email || user.email,\n    vehicle: vehicle ? {\n      id: vehicle.id,\n      vehicle_number: vehicle.vehicleNumber || vehicle.vehicle_number,\n      vehicle_type: vehicle.vehicleType || vehicle.vehicle_type,\n      route_id: vehicle.routeId || null,\n      data: vehicle\n    } : null\n  };\n}\n\nasync function loadDriver() {\n  let profile = await myDriverProfile().catch((error) => {\n    console.warn(\"Supabase driver profile unavailable, using Firestore fallback\", error);\n    return null;\n  });\n  if (!profile) profile = await fallbackDriverProfile(state.user);\n  state.profile = profile;\n  if (!profile) {\n    setText(\"driverName\", \"Driver profile not found\");\n    setText(\"driverNote\", \"Admin se vehicle edit karke driver email/password save karwao, phir login retry karo.\");\n    return;\n  }\n  setText(\"driverName\", profile.name);\n  setText(\"vehicleNumber\", profile.vehicle?.vehicle_number || \"Not assigned\");\n  state.map = await createVehicleMap($(\"driverMap\"), { zoom: 15 });\n  await updatePermissionUi();\n  startBrowserWatch();\n  await refreshTrip();\n  if (profile.vehicle?.id) {\n    subscribeTransport(\"schoolix_transport_trips\", `vehicle_id=eq.${profile.vehicle.id}`, refreshTrip, refreshTrip);\n  }\n}\nwindow.SchoolixNativeLocationStatus = {\n  receiveStatus(payload = {}) {\n    setText(\"gpsStatus\", payload.status || \"Connected\");\n    if (payload.updatedAt) setText(\"lastUpdate\", relativeTime(payload.updatedAt));\n  }\n};\n$(\"grantPermissionBtn\").addEventListener(\"click\", async () => {\n  if (window.SchoolixNativeLocation?.requestLocationPermission) window.SchoolixNativeLocation.requestLocationPermission();\n  else navigator.geolocation?.getCurrentPosition(() => updatePermissionUi(), () => updatePermissionUi(), { enableHighAccuracy: true });\n  setTimeout(updatePermissionUi, 1200);\n});\n$(\"logoutBtn\").addEventListener(\"click\", async () => {\n  if (state.activeTrip || state.nativeTripId || $(\"trackingStatus\").classList.contains(\"on\")) {\n    setText(\"driverNote\", \"Logout is locked while location tracking is ON. Ask the administrator to stop the trip first.\");\n    return;\n  }\n  stopBrowserWatch();\n  await signOut(auth);\n  location.href = \"#/index.html\";\n});\nsetInterval(() => setText(\"lastUpdate\", relativeTime(state.lastLocationAt)), 3000);\nonAuthStateChanged(auth, async (user) => {\n  if (!user) { location.href = \"#/index.html\"; return; }\n  state.user = user;\n  const userProfile = await findDriverUserProfile(user);\n  if (!userProfile || String(userProfile.role || \"\").toLowerCase() !== \"driver\") {\n    alert(\"Access denied. Driver account required.\");\n    location.href = \"#/index.html\";\n    return;\n  }\n  await loadDriver();\n});\n"},{"attributes":{"src":"schoolix-polish.js"},"text":""}]};
